-- Controles confirmados por el propietario el 15/10/2026; sólo contenido editorial.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES ('seguridad-registro-validacion-pagos',$texto$Registrar y validar sin duplicados: cargo único, cancelar modal y dos pestañas$texto$,'Cobranza',$texto$Comprobar que un cargo no se seleccione dos veces, que cancelar la confirmación no registre pagos y que validar el mismo folio desde dos pestañas publique un solo ingreso y abono.$texto$,$texto$Alumno e inscripción vigentes, tutor financiero vinculado, concepto de prueba sin beca/descuento/recargo, cuenta activa de tipo Caja en MXN con apertura anterior al pago, administrador identificado autorizado para registrar y validar. Pruebas controladas sin efectivo real. Si los ensayos ya se realizaron, consultar sus registros y no repetirlos ni cancelar pagos para volver a probar. Para reproducir desde cero usar otro concepto/adeudo de200, con fechas dentro de inscripción/ciclo y usuario presente; las operaciones las captura el usuario, no el agente.$texto$,$texto$Confirmaciones del 15/10/2026: en DUP-TEST se bloqueó la selección repetida y Cancelar modal conservó la captura sin registrar; el pago PAG-20261015-000029 tuvo un solo ingreso200 y un abono200 aunque la interfaz antigua mostraba éxito dos veces. Se corrigió el aviso y el propietario confirmó otro ensayo DUP-TEST-02: segunda pestaña indica ya validado/sin movimientos adicionales y cuenta sólo+200. No se conoce su folio ni se atribuye un saldo absoluto. El recorrido siguiente permite reproducir los tres controles con un nuevo adeudo200; no exige repetir los casos ya terminados.$texto$,1,DATE '2026-10-15','CONFIRMADA');

INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['INSCRIPCION_LEER','TUTOR_LEER','CONCEPTO_COBRO_ADMINISTRAR','CUOTA_ALUMNO_ADMINISTRAR','CARGO_ADMINISTRAR','PAGO_REGISTRAR','PAGO_LEER','PAGO_VALIDAR','CUENTA_FINANCIERA_LEER']) WHERE g.slug='seguridad-registro-validacion-pagos';

INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.numero,v.titulo,v.perfil,v.modulo,v.instrucciones,v.ejemplo,v.resultado,v.precaucion,v.ruta FROM guia_proceso g JOIN (VALUES
('seguridad-registro-validacion-pagos',1,$texto$Identificar alumno, tutor y caja del ensayo$texto$,$texto$Administración$texto$,$texto$Inscripciones, Tutores y Cuentas financieras$texto$,$texto$1. Entra a Operación escolar → Control escolar → Inscripciones, busca el alumno de prueba → Aplicar filtros → Editar; revisa institución, plantel, ciclo y fechas que incluyan el día de vencimiento elegido. 2. Entra a Operación escolar → Control escolar → Tutores, busca al tutor y comprueba que sea responsable financiero vigente del alumno; conserva matrícula y tutor para no mezclar otros hijos. 3. En Administración → Finanzas → Cuentas financieras busca la caja del plantel → Aplicar filtros; comprueba Activa, tipo Caja, MXN y apertura anterior al pago. Anota Saldo actual como S, no Saldo inicial. 4. Conserva esos datos y evita otros movimientos en la cuenta durante el ensayo. Si ya se realizó, consulta el pago y su movimiento histórico sin registrar otro para comprobarlo.$texto$,$texto$Saldo S ilustrativo5000; al validar un único pago200 debe quedar5200, nunca5400.$texto$,$texto$Contexto identificado sin operaciones financieras.$texto$,$texto$No usar el acceso de recuperación para validar ni mezclar esta prueba con el pago anual11000 o devoluciones1400.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('seguridad-registro-validacion-pagos',2,$texto$Crear un concepto exclusivo y confirmar su resumen$texto$,$texto$Administración$texto$,$texto$Conceptos de cobro$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Conceptos de cobro → Nuevo registro; selecciona institución. Para un ensayo nuevo captura código SEG-PAGO-TEST, nombre Prueba de controles de pago y categoría Otro. Si ese código ya se usó, utiliza uno nuevo y conserva el mismo en todos los pasos siguientes. 2. Deja Permite beca, Permite descuento y Permite recargo desactivados; activa Concepto activo. No cambies conceptos operativos compartidos para hacer pruebas. 3. Pulsa Crear concepto y revisa el modal: institución, código, nombre, categoría y reglas Sí/No. Cancelar permite corregir sin guardar; confirma con Confirmar y crear concepto cuando coincida. 4. Comprueba el concepto en el listado. En los casos confirmados se usaron DUP-TEST y DUP-TEST-02; esos códigos ya utilizados no deben producir otro pago del mismo adeudo.$texto$,$texto$Concepto activo, categoría Otro, sin beca ni ajustes; no se configura monto aquí.$texto$,$texto$Concepto listo para una cuota200.$texto$,$texto$El modal de concepto sólo crea el catálogo, no un adeudo o ingreso.$texto$,$texto$/admin/catalogos/conceptos-cobro$texto$),
('seguridad-registro-validacion-pagos',3,$texto$Configurar una cuota única de $200$texto$,$texto$Administración$texto$,$texto$Cuotas por alumno$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Cuotas por alumno → Crear cuota; selecciona institución, plantel, inscripción y el concepto exclusivo del paso anterior. 2. Captura Importe individual200.00, MonedaMXN, ¿Cada cuándo se cobrará? Una sola vez y Fecha límite de pago20/10/2026 como fecha ilustrativa del ensayo realizado el15/10/2026; para otro momento adapta el vencimiento dentro de inscripción/ciclo. 3. Selecciona Estado Activa e Incluir en generación automática de cargos. Abre Configuración adicional y comprueba que la vigencia incluya el vencimiento sin rebasar la inscripción/ciclo. 4. Pulsa Crear cuota, revisa alumno, concepto, importe y fecha en el modal y confirma una sola vez. Si consultas una cuota ya generada, no la dupliques ni canceles su cargo para regenerarlo.$texto$,$texto$Una cuota única200, sin beca/recargo/descuento.$texto$,$texto$Cuota preparada, caja permanece S.$texto$,$texto$Una cuota única no se repite cada mes. Para otro ensayo crea un concepto/adeudo nuevo, no reutilices el liquidado.$texto$,$texto$/admin/cuotas-alumno/nuevo$texto$),
('seguridad-registro-validacion-pagos',4,$texto$Generar sólo el nuevo adeudo$texto$,$texto$Administración$texto$,$texto$Adeudos de alumnos → Generar automáticos$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos → Generar automáticos, selecciona institución/plantel y Generar hasta20/10/2026 para el ejemplo; adapta el corte si usaste otra fecha. 2. Pulsa Visualizar cuotas por aplicar → Desmarcar todos y marca exclusivamente la fila del alumno y concepto nuevo por200; revisa beca0 y neto200. 3. Pulsa Confirmar y generar adeudos seleccionados, revisa el modal y confirma una vez. Luego pulsa Volver a adeudos de alumnos. 4. En Buscar captura alumno/matrícula, en Concepto de cobro el código elegido → Aplicar filtros; abre Ver y anota ID, periodo y saldo pendiente200. Debe existir un solo cargo, sin abonos.$texto$,$texto$Un cargo200, todavía sin pago ni ingreso.$texto$,$texto$Adeudo controlado identificado por ID y alumno.$texto$,$texto$No generar otros pendientes de la familia ni usar los adeudos800 del acuerdo devuelto.$texto$,$texto$/admin/cargos/generar$texto$),
('seguridad-registro-validacion-pagos',5,$texto$Seleccionar una vez el adeudo en un nuevo pago$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Nuevo registro$texto$,$texto$1. Entra a Administración → Finanzas → Pagos recibidos → Nuevo registro. Selecciona institución, plantel y tutor responsable del alumno de prueba. 2. En Adeudos que se van a pagar → Cargo del alumno da foco para primeras opciones o escribe tres caracteres del concepto; selecciona el cargo200 identificado. Si no existe fila, pulsa Agregar cargo. 3. Revisa alumno, concepto y periodo; el Importe que se aplicará debe cargar200 y quedar protegido. No actives Registrar pago parcial ni dinero pendiente de asignar. 4. Comprueba Total recibido200 y Distribuido entre cargos200, con dinero pendiente de asignar0. Todavía no pulses Registrar como pendiente.$texto$,$texto$Una fila del cargo200; sin abono ni ingreso mientras no se valide.$texto$,$texto$Captura inicial con total correcto.$texto$,$texto$No confundir dos cargos del mismo concepto con el mismo cargo: se compara ID, alumno y periodo.$texto$,$texto$/admin/pagos/nuevo$texto$),
('seguridad-registro-validacion-pagos',6,$texto$Intentar seleccionar otra vez exactamente el mismo cargo$texto$,$texto$Administración$texto$,$texto$Registrar pago → Asignación por cargo y alumno$texto$,$texto$1. En la misma captura pulsa Agregar cargo para abrir una segunda fila. Da foco en Cargo del alumno o busca el mismo código del concepto. 2. Comprueba que el cargo ya elegido no vuelva a aparecer; otros adeudos distintos sí pueden seguir disponibles. Si no hay otros resultados, la ayuda indica que los ya agregados no se repiten. 3. Si una opción quedó abierta antes de elegir ese cargo en otra fila, intentar seleccionarla debe mostrar Este adeudo ya está incluido en el pago, sin asignarla ni aumentar el total. Esa protección también cubre respuestas antiguas del buscador; no hace falta manipular el navegador para reproducirla. 4. Quita la fila adicional vacía con × y deja sólo el cargo200. Verifica total200, no400, antes de continuar. Quitar una fila sólo cambia esta captura, no cancela el adeudo.$texto$,$texto$Cargo duplicado excluido; un único200 seleccionado.$texto$,$texto$Control contra selección duplicada confirmado.$texto$,$texto$El servidor conserva además la validación de un cargo una sola vez por distribución; no desactives controles para probarla.$texto$,$texto$/admin/pagos/nuevo$texto$),
('seguridad-registro-validacion-pagos',7,$texto$Cancelar el modal sin registrar un pago$texto$,$texto$Administración$texto$,$texto$Registrar pago → Datos del pago y confirmación$texto$,$texto$1. En Datos del pago captura Método Efectivo, Cuenta declarada de tipo Caja identificada, Fecha y hora actuales no futuras y Referencia PRUEBA-CANCELAR-MODAL-200. Conserva importe200 calculado desde el cargo. 2. Pulsa Registrar como pendiente; revisa alumno, cuenta e importe200 en el modal. Pulsa Cancelar DENTRO del modal, no el enlace Cancelar del formulario. 3. Comprueba que sólo se cierre el modal y que todos los campos permanezcan capturados. En otra pestaña entra a Administración → Finanzas → Pagos recibidos, busca referencia PRUEBA-CANCELAR-MODAL-200 → Aplicar filtros: no debe haberse creado un nuevo pago por este intento. 4. Consulta también el adeudo y la caja: saldo del cargo200 sin abonos y cuenta S sin cambios. Si ya existía una prueba con esa referencia, identifica registros por folio/fecha o usa una referencia nueva para comparar sin ambigüedad.$texto$,$texto$Cancelar modal: cero nuevos pagos, cero abonos y cero ingresos.$texto$,$texto$Cancelación de confirmación sin guardar confirmada.$texto$,$texto$No cierres el formulario antes de comprobar que se conservó la captura; úsala para el siguiente paso.$texto$,$texto$/admin/pagos/nuevo$texto$),
('seguridad-registro-validacion-pagos',8,$texto$Registrar un único pago pendiente$texto$,$texto$Administración$texto$,$texto$Registrar pago → Confirmar registro$texto$,$texto$1. Regresa a la captura conservada con un solo cargo200, Método Efectivo y la misma caja; cambia Referencia a PRUEBA-DOS-PESTANAS-200 o una referencia nueva exclusiva del ensayo. 2. Pulsa Registrar como pendiente, revisa el modal y esta vez confirma. Espera a que se genere un folio automático PAG y anótalo. 3. Comprueba recepción pendiente por200; el registro no debe haber publicado ingreso ni reducido el cargo todavía. Consulta cajaS y adeudo200 si necesitas confirmar. 4. No registres otro pago en otra pestaña ni vuelvas a enviar el formulario nuevo. La siguiente prueba utilizará dos vistas de ESTE MISMO folio ya creado.$texto$,$texto$Un registro pendiente200 con folio único.$texto$,$texto$Pago pendiente listo para validar.$texto$,$texto$Para repetir tras haberlo validado hace falta otro adeudo de ensayo; no canceles ni dupliques el pago válido anterior.$texto$,$texto$/admin/catalogos/pagos$texto$),
('seguridad-registro-validacion-pagos',9,$texto$Abrir el mismo folio pendiente en dos pestañas$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Ver → Gestión$texto$,$texto$1. Entra a Administración → Finanzas → Pagos recibidos, busca el folio o referencia del paso anterior → Aplicar filtros → Ver → Gestión. 2. Duplica ESA pestaña del navegador, no la pantalla Nuevo registro. Comprueba que ambas URL corresponden al mismo ID y que muestran el mismo folio, estado pendiente e importe200. 3. Mantén ambas vistas abiertas antes de validar. En una tercera pestaña consulta Cuentas financieras y vuelve a anotar Saldo actual S de la misma caja inmediatamente antes del primer intento. 4. No cierres sesión ni recargues la segunda pestaña durante la prueba; de lo contrario podría mostrar ya Validado y no conservar el formulario antiguo que se quiere comprobar.$texto$,$texto$Dos pestañas de un pago, no dos pagos diferentes.$texto$,$texto$Situación de pestaña desactualizada preparada.$texto$,$texto$Las pestañas administrativas comparten sesión; deben estar bajo un usuario autorizado vigente.$texto$,$texto$/admin/catalogos/pagos$texto$),
('seguridad-registro-validacion-pagos',10,$texto$Validar desde la primera pestaña$texto$,$texto$Administración$texto$,$texto$Detalle del pago → Gestión → Validar y publicar$texto$,$texto$1. En la primera pestaña revisa cuenta destino y monto200 dentro de Control administrativo del pago; no actives cambio de cuenta ni importe recibido mayor. 2. Pulsa Validar y publicar, revisa el modal y confirma una sola vez. Espera a que termine y muestre el pago validado con el mensaje de publicación habitual. 3. En Resumen comprueba Movimiento único de ingreso200; en Distribución debe existir un abono200 y saldo del cargo0. No realices otro movimiento para obtener ese resultado. 4. Conserva intacta la segunda pestaña que todavía muestra pendiente; no la actualices antes del siguiente paso.$texto$,$texto$Primer intento: un ingreso200 y un abono200.$texto$,$texto$Pago publicado una vez.$texto$,$texto$Si la primera validación falla, detén la prueba y resuelve la causa; no continúes como si se hubiera publicado.$texto$,$texto$/admin/catalogos/pagos$texto$),
('seguridad-registro-validacion-pagos',11,$texto$Intentar validar desde la segunda pestaña antigua$texto$,$texto$Administración$texto$,$texto$Segunda pestaña → Gestión → Validar y publicar$texto$,$texto$1. En la segunda pestaña SIN RECARGAR pulsa Validar y publicar y confirma el modal del mismo folio por200. 2. Debe abrirse el expediente actualizado con aviso ámbar Este pago ya estaba validado y el texto Este pago ya fue validado desde otra pestaña o por otro usuario. No se realizó ningún movimiento adicional. 3. Comprueba que no muestre un nuevo éxito de publicación ni una página de error técnico. El servidor devuelve el estado ya publicado sin repetir ingreso, abono o auditoría de validación. 4. Conserva evidencia del aviso y pasa a comparar saldos. No registres otro pago porque la segunda pestaña no ejecutó una nueva operación.$texto$,$texto$Segundo intento informa repetición, sin aumento adicional200.$texto$,$texto$Aviso y protección financiera confirmados por el propietario.$texto$,$texto$El aviso no es un error de la cuenta ni pide una devolución. El pago válido se conserva y no debe cancelarse.$texto$,$texto$/admin/catalogos/pagos$texto$),
('seguridad-registro-validacion-pagos',12,$texto$Verificar una sola publicación y cerrar esta ronda$texto$,$texto$Administración$texto$,$texto$Pagos recibidos, Adeudos de alumnos y Cuentas financieras$texto$,$texto$1. En Administración → Finanzas → Pagos recibidos busca la referencia/folio: debe existir un solo pago200 Validado. Abre Ver → Resumen: un movimiento de ingreso200; Distribución: un abono vigente200 al cargo. 2. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; Busca alumno y Concepto de cobro del ensayo → Todos o Liquidado → Aplicar filtros → Ver: saldo pendiente0 y abonado200, sin ajustes para forzar la liquidación. 3. Entra a Administración → Finanzas → Cuentas financieras, consulta la misma caja → Aplicar filtros: saldo S+200, nunca S+400. Si hubo otros movimientos concurrentes, contrasta el único movimiento del folio; no confundas el saldo inicial con el saldo previo S. 4. Conserva evidencias y termina sin cancelar el pago correcto. El propietario confirmó los tres controles; esta ronda de cobranza queda completada, no significa que se hayan probado todas las combinaciones posibles del sistema.$texto$,$texto$Un pago200, un abono200, un ingreso200 y cargo0; S+200.$texto$,$texto$Tres pruebas confirmadas y ronda de cobranza concluida.$texto$,$texto$No repetir los ensayos ya terminados. Propuesta de siguiente validación: cierre de caja y reportes financieros, como proceso separado.$texto$,$texto$/admin/catalogos/pagos$texto$)
) v(slug,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta) ON g.slug=v.slug;

-- Sustituir referencias a pendientes ya confirmados, sin editar migraciones aplicadas.
UPDATE guia_proceso_paso SET precaucion=$texto$Cargo duplicado, cancelar confirmación sin guardar y validar el mismo folio desde dos pestañas ya fueron confirmados y tienen guía propia: Registrar y validar sin duplicados. No repetir pagos ni alterar el caso ya terminado. Devoluciones del beneficio fijo y pago anual también cuentan con guías confirmadas.$texto$
WHERE (guia_id IN (SELECT id FROM guia_proceso WHERE slug IN ('pago-anticipado-beca-porcentaje','anticipo-mensualidad-bonificada','anticipo-sustituir-beca','anticipo-beneficio-fijo','devolver-acuerdo-anticipado')) AND numero=10)
 OR (guia_id IN (SELECT id FROM guia_proceso WHERE slug IN ('cancelar-pago-anticipado-beca','pago-anual-diciembre-bonificado')) AND numero=12);
UPDATE guia_proceso_paso SET precaucion=$texto$No cancelar el pago ni aplicar descuentos manuales para cerrar el ejercicio anual. Devoluciones del otro acuerdo1400 y los tres controles de seguridad ya tienen guías confirmadas independientes; no afectan este pago anual.$texto$
WHERE guia_id=(SELECT id FROM guia_proceso WHERE slug='pago-anual-diciembre-bonificado') AND numero=11;
UPDATE guia_proceso_paso SET instrucciones=replace(instrucciones,'seguridad de cargo duplicado, cancelar confirmación y validar un mismo pago desde dos pestañas son los tres ensayos pendientes.','los tres controles de seguridad ya están confirmados y documentados en la guía Registrar y validar sin duplicados.')
WHERE guia_id=(SELECT id FROM guia_proceso WHERE slug='devolver-acuerdo-anticipado') AND numero=10;
UPDATE guia_proceso SET version_contenido=version_contenido+1,revisada_el=DATE '2026-10-15'
WHERE slug IN ('pago-anticipado-beca-porcentaje','anticipo-mensualidad-bonificada','anticipo-sustituir-beca','anticipo-beneficio-fijo','devolver-acuerdo-anticipado','cancelar-pago-anticipado-beca','pago-anual-diciembre-bonificado');
